pm.test("Login réussi (200)", () => pm.response.to.have.status(200));

const json = pm.response.json();
pm.test("Token présent", () =>
  pm.expect(json.authentication.token).to.be.a("string"));

pm.environment.set("token", json.authentication.token);
pm.environment.set("basketId", json.authentication.bid);

pm.test("Status 200", () => pm.response.to.have.status(200));

pm.test("Réponse en moins de 1000 ms", () =>
  pm.expect(pm.response.responseTime).to.be.below(1000));

pm.test("La liste des produits est présente", () => {
  const json = pm.response.json();
  pm.expect(json.data).to.be.an("array");
  pm.expect(json.data.length).to.be.above(0);
});
